PRAGMA foreign_keys=ON;
BEGIN;
CREATE TABLE IF NOT EXISTS w100_evidence(object_id TEXT REFERENCES w100_objects(id),source_id TEXT REFERENCES w100_sources(id),PRIMARY KEY(object_id,source_id));
CREATE TABLE IF NOT EXISTS w100_sources(id TEXT PRIMARY KEY,title TEXT NOT NULL,url TEXT NOT NULL,locator TEXT NOT NULL,revision TEXT,visibility TEXT NOT NULL,observed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS w100_layers(assembly_id TEXT REFERENCES w100_objects(id),ordinal INTEGER,material TEXT NOT NULL,thickness_mm REAL CHECK(thickness_mm IS NULL OR thickness_mm>=0),geometry TEXT NOT NULL,PRIMARY KEY(assembly_id,ordinal));
CREATE TABLE IF NOT EXISTS w100_objects(id TEXT PRIMARY KEY,kind TEXT NOT NULL,title TEXT NOT NULL,payload_json TEXT NOT NULL,version TEXT NOT NULL,status TEXT NOT NULL);
